struct Guard { int& n; explicit Guard(int& x): n(x) { ++n; } ~Guard() { --n; } Guard(const Guard&) = delete; Guard& operator=(const Guard&) = delete; };
int solve(int a, int b) { int n = a, peak; { Guard x{n}; Guard y{n}; peak = n; } return peak + n + b; }
